#!/bin/bash
set -euo pipefail

run=/tmp/runs/bp-p0b-5966e84-20260715a
repo=/tmp/yeto-best-paper
phase_map="$run/phase-map"
inputs="$run/inputs"
model_archive="$inputs/model-93efa2f.tar"
model_dir="$inputs/model"
data_path="$inputs/train.parquet"
parent="$run/parent"

test "$(git -C "$repo" rev-parse HEAD)" = '8d58208cacafef12cb95f2642b4fa700531151b4'
test "$(git -C "$repo" rev-parse --is-shallow-repository)" = false
git -C "$repo" cat-file -e '16d27bc60deb6d8910bf0111c7fb57c9d0eb5b80^{commit}'
git -C "$repo" cat-file -e '5966e8432e0c350d8968000289656cce2a22fc9d^{commit}'
git -C "$repo" cat-file -e '8d58208cacafef12cb95f2642b4fa700531151b4^{commit}'
git -C "$repo" merge-base --is-ancestor   16d27bc60deb6d8910bf0111c7fb57c9d0eb5b80 8d58208cacafef12cb95f2642b4fa700531151b4
git -C "$repo" merge-base --is-ancestor   5966e8432e0c350d8968000289656cce2a22fc9d 8d58208cacafef12cb95f2642b4fa700531151b4
test "$(git -C "$repo" show '8d58208cacafef12cb95f2642b4fa700531151b4:docs/AMENDMENT-parallel-cells.md' | sha256sum | awk '{print $1}')" =   'e2c87fd6c2ec0e4b91f488b5771334e0befd175560a3e2ccfcf349be1ee8b3dd'
test -z "$(git -C "$repo" status --porcelain=v1 --untracked-files=all)"

test ! -e "$inputs" || {
  echo 'input staging directory already exists' >&2
  exit 31
}
test ! -e "$parent" || {
  echo 'parent staging directory already exists' >&2
  exit 32
}
mkdir -p "$model_dir" "$parent" "$phase_map"

printf %s  | base64 -d > "$parent/p0a-phase-map-manifest.json"
printf %s  | base64 -d > "$parent/p0a-replay-report.json"
printf '%s  %s
'   'f299175a0924da6b99820e5cd63ac0ccaa4d7f307e8358e2ba78e575f91bd885'   "$parent/p0a-phase-map-manifest.json" | sha256sum -c -
printf '%s  %s
'   '4c1616de16708590d6a30aaf3af805adc4bad47b827087b49251d678e200c276'   "$parent/p0a-replay-report.json" | sha256sum -c -

test -f "$run/provider-evidence.json"
test ! -L "$run/provider-evidence.json"
test ! -e "$phase_map/provider-evidence.json"
cp -- "$run/provider-evidence.json" "$phase_map/provider-evidence.json"
cmp -- "$run/provider-evidence.json" "$phase_map/provider-evidence.json"

gcloud storage cp   'gs://yeto-exp2-52-model-training-497007/prelaunch/bp-p0a-0af7f4a-20260714a/model-93efa2f.tar#1784089423172165'   "$model_archive"
printf '%s  %s
'   '53d15a96a333e33c6a7a9224dbe6392a2480420bd40a327588797d03b625e4c3'   "$model_archive" | sha256sum -c -
tar -xf "$model_archive" -C "$model_dir"
(cd "$model_dir" && sha256sum -c model-files.sha256)
test "$(cat "$model_dir/model-id.txt")" = 'HuggingFaceTB/SmolLM2-135M'
test "$(cat "$model_dir/model-revision.txt")" =   '93efa2f097d58c2a74874c7e644dbc9b0cee75a2'

gcloud storage cp   'gs://yeto-exp2-52-model-training-497007/prelaunch/bp-p0a-0af7f4a-20260714a/train.parquet#1784090284099303'   "$data_path"
printf '%s  %s
'   '970f88b3f2fa6758f3b5f94052f4e91b872541a2ba530223b44a779168c51409'   "$data_path" | sha256sum -c -

PYTHONPATH="$repo" /home/shou/venv/bin/python /tmp/yeto-best-paper/scripts/run_phase_map.py --phase execute --study-id bp-phase-map-p0b --study-phase p0b_canary --run-dir /tmp/runs/bp-p0b-5966e84-20260715a/phase-map --artifact-uri gs://yeto-exp2-52-model-training-497007/bp-p0b-5966e84-20260715a/phase-map --git-commit 8d58208cacafef12cb95f2642b4fa700531151b4 --python-executable /home/shou/venv/bin/python --command-repo-root /tmp/yeto-best-paper --image-digest 038098c2b5356c9117f1019bf0d19c8999ab50f259dceb041a57fcf657d2620f --image-numeric-id 7290368630472593484 --model-path /tmp/runs/bp-p0b-5966e84-20260715a/inputs/model --model-revision 93efa2f097d58c2a74874c7e644dbc9b0cee75a2 --data /tmp/runs/bp-p0b-5966e84-20260715a/inputs/train.parquet --expected-model-hash 43f9494fad3335a9237f7a3093ae1401b7c4d3164c7486542070e2cc04837132 --expected-data-hash 970f88b3f2fa6758f3b5f94052f4e91b872541a2ba530223b44a779168c51409 --expected-train-rows-hash 55f92573ceae6ca77ed58b58afd6554ae4fbde8e0d47ed83dea35a4862f97cfd --expected-development-eval-rows-hash 533838a0564b13519956a044d23ed8db6705ddc7ae5f0ddb96538f49460bcebc --expected-development-eval-packed-hash 865be921dfa890e26f5ddd2b268fdecfb6e90bca4048d0760012b7cb60b25cb4 --expected-development-eval-example-ids-hash 4378783ade97d6529729082302d2794de6a559fc618d7acfbe8d3c3a6968baf2 --expected-development-eval-token-ids-hash fe488ba475717621b7559e9406924bb2543a5307317dc6b224a99045e1eee642 --expected-development-eval-source-indices-hash 58108d24b4976523f033a8628384e962195a6f2a68b2bad2b32c77c0c7603740 --expected-audit-eval-rows-hash d71b90040a57731f25c78a2d191017ce90a12c1bb79f55a1cd2f3d085a706d7b --expected-audit-eval-packed-hash c08d196e15a0b1ee88e64da11521564de2c42d56857ef899b3ba91478ba47f7f --expected-audit-eval-example-ids-hash c7be2d71515850da85a3b9d9fa0bf27b56310a25f4b5d009d46ebe887edc1170 --expected-audit-eval-token-ids-hash 5b725289d3308a0b8f64ea0e2a49195e9aa95b8dfaf5b9359644250426c00b41 --expected-audit-eval-source-indices-hash 1b1